CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'customer',status VARCHAR(20) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS settings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(190) NOT NULL UNIQUE,setting_value LONGTEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS menus(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,url VARCHAR(500) NOT NULL,location VARCHAR(50) NOT NULL DEFAULT 'header',sort_order INT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'active') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,content LONGTEXT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,description TEXT NULL,sort_order INT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'active') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NULL,name VARCHAR(190) NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,short_description TEXT NULL,description LONGTEXT NULL,price DECIMAL(12,2) NOT NULL DEFAULT 0,image VARCHAR(500) NULL,delivery_type VARCHAR(30) NOT NULL DEFAULT 'manual',status VARCHAR(20) NOT NULL DEFAULT 'draft',sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_products_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,order_no VARCHAR(50) NOT NULL UNIQUE,subtotal DECIMAL(12,2) NOT NULL DEFAULT 0,discount_total DECIMAL(12,2) NOT NULL DEFAULT 0,coupon_code VARCHAR(64) NULL,coupon_usage_released TINYINT(1) NOT NULL DEFAULT 0,total DECIMAL(12,2) NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'pending',payment_status VARCHAR(30) NOT NULL DEFAULT 'unpaid',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_orders_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,seller_id BIGINT UNSIGNED NULL,seller_commission_rate DECIMAL(5,2) NOT NULL DEFAULT 10.00,discount_amount DECIMAL(12,2) NOT NULL DEFAULT 0.00,product_name VARCHAR(190) NOT NULL,quantity INT NOT NULL DEFAULT 1,unit_price DECIMAL(12,2) NOT NULL,CONSTRAINT fk_items_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS coupons(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(64) NOT NULL UNIQUE,discount_type VARCHAR(16) NOT NULL DEFAULT 'percent',discount_value DECIMAL(12,2) NOT NULL,min_order DECIMAL(12,2) NOT NULL DEFAULT 0,max_discount DECIMAL(12,2) NULL,usage_limit INT UNSIGNED NOT NULL DEFAULT 0,usage_count INT UNSIGNED NOT NULL DEFAULT 0,starts_at DATETIME NULL,expires_at DATETIME NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_coupon_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payment_transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,provider VARCHAR(30) NOT NULL,provider_reference VARCHAR(190) NULL,amount DECIMAL(12,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_payment_provider_reference(provider,provider_reference),CONSTRAINT fk_payment_order FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;